namespace Raavi.Application.Abstractions.Email;

/// <summary>An outgoing e-mail. Bodies are generated by Raavi (never raw user HTML).</summary>
public sealed record EmailMessage(string To, string ToName, string Subject, string TextBody, string HtmlBody);

/// <summary>
/// Sends transactional e-mail (notifications). Configured globally in <c>sandbox/config/notifications.json</c>
/// (<c>Raavi:Email</c>); the SMTP password comes from the environment or a secret store, never from the file.
/// </summary>
public interface IEmailSender
{
    /// <summary>False when e-mail is switched off (<c>Mode = Disabled</c>): callers record the message as skipped.</summary>
    bool IsEnabled { get; }

    Task SendAsync(EmailMessage message, CancellationToken cancellationToken = default);
}
